import {chromium,webkit} from 'playwright';import fs from 'node:fs';import crypto from 'node:crypto';import assert from 'node:assert/strict';
const engine=process.env.BROWSER??'chromium',out=`qa-output/${engine}`;fs.mkdirSync(out,{recursive:true});const browser=await ({chromium,webkit}[engine]).launch({headless:true,args:engine==='chromium'?['--use-angle=swiftshader']:[]});const page=await browser.newPage({viewport:{width:1440,height:1000},deviceScaleFactor:1});const errors=[],consoleMessages=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{consoleMessages.push({type:m.type(),text:m.text()});if(m.type()==='error')errors.push(m.text());});let result;
try{
 page.setDefaultTimeout(120000);await page.goto('http://127.0.0.1:8765/index.html',{waitUntil:'networkidle'});await page.waitForFunction(()=>window.__plantStudy?.state.frames>=3,{timeout:120000});await page.waitForTimeout(1200);await page.evaluate(()=>window.__plantStudy.setTime(2));assert.equal(await page.locator('#error').isVisible(),false);result=await page.evaluate(()=>window.__plantStudy.evidence());assert.equal(result.shaderErrors.length,0);assert.equal(result.videoElements,0);assert.ok(result.geometry.venation>3000);
 await page.screenshot({path:`${out}/01-default.png`});const before=await page.evaluate(()=>Array.from(window.__plantStudy.study.leaves[0].geometry.attributes.position.array.slice(18000,18015)));
 await page.locator('#curl').evaluate((el,v)=>el.value=v,'5.80');await page.locator('#curl').dispatchEvent('input');await page.waitForTimeout(700);const after=await page.evaluate(()=>Array.from(window.__plantStudy.study.leaves[0].geometry.attributes.position.array.slice(18000,18015)));assert.notDeepEqual(before,after);await page.screenshot({path:`${out}/02-curled.png`});
 await page.locator('#curl').evaluate((el,v)=>el.value=v,'0.35');await page.locator('#curl').dispatchEvent('input');await page.locator('#front').click();await page.waitForTimeout(700);await page.screenshot({path:`${out}/03-flat-front.png`});
 await page.locator('#side').click();await page.waitForTimeout(700);await page.screenshot({path:`${out}/04-side.png`});
 await page.locator('#reset').click();await page.locator('#curl').evaluate((el,v)=>el.value=v,'5.10');await page.locator('#curl').dispatchEvent('input');await page.locator('#near').click();await page.waitForTimeout(700);await page.screenshot({path:`${out}/05-macro.png`});
 await page.locator('#layers').evaluate((el,v)=>el.value=v,'1');await page.locator('#layers').dispatchEvent('input');assert.equal(await page.evaluate(()=>window.__plantStudy.study.leaves.filter(x=>x.visible).length),1);await page.locator('#layers').evaluate((el,v)=>el.value=v,'3');await page.locator('#layers').dispatchEvent('input');
 await page.locator('#baseline').click();for(let i=0;i<64;i++)await page.locator('#teacher-step').click();assert.match(await page.locator('#teacher-count').textContent(),/846/);await page.screenshot({path:`${out}/06-original-algorithm-64.png`});await page.locator('#applied').click();
 for(let i=0;i<3;i++){await page.locator('#source').click();assert.ok(await page.locator('#source-dialog').isVisible());await page.keyboard.press('Escape');assert.equal(await page.locator('#source-dialog').isVisible(),false);}
 await page.locator('#reset').click();await page.setViewportSize({width:390,height:844});await page.waitForTimeout(800);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);await page.screenshot({path:`${out}/07-mobile.png`,fullPage:true});
 result={...result,engine,passed:true,errors,tests:['real WebGL render','3D curl buffer changes','front/side/close cameras','layer toggle','time pause','original 64-step count','repeated dialog close','mobile overflow']};assert.deepEqual(errors,[]);
}catch(e){result={...result,engine,passed:false,error:e.stack,errors};await page.screenshot({path:`${out}/failure.png`,fullPage:true}).catch(()=>{});throw e;}finally{fs.writeFileSync(`${out}/result.json`,JSON.stringify(result,null,2));fs.writeFileSync(`${out}/console.json`,JSON.stringify(consoleMessages,null,2));await browser.close();}
